import jwt from 'jsonwebtoken';
const secretString = process.env.SECRET_STRING

// authMiddleware.js
const checkTokenBlacklist = async (req, res, next) => {
    const token = req.headers.authorization?.split(' ')[1];
    
    if (!token) {
      return res.status(401).json({ error: "No token provided" });
    }
  
    // Check if token is blacklisted
    const isBlacklisted = await client.get(`blacklist:${token}`);
    
    if (isBlacklisted) {
      return res.status(401).json({ error: "Token invalidated (logged out)" });
    }
  
    next(); // Token is valid, proceed
  };
  
  // Apply to protected routes
  router.get('/protected-route', checkTokenBlacklist, (req, res) => { ... });

export const tokenChecker = (req, res, next) => {
    const authHeader = req.get('Authorization');
    
    if (!authHeader) {
        return res.status(401).json({ error: 'No token provided, please log in.' }); // Add `return` here
    }

    const token = authHeader.split(' ')[1];
    let decodedToken;

    try {
        decodedToken = jwt.verify(token, secretString);
        if (!decodedToken) {
            return res.status(401).json({ error: 'Invalid token, please log in again.' }); // Add `return` here
        }

            req.user = {
            _id: decodedToken.id,
            role: decodedToken.role,
        };
              console.log(req.user)
        next(); 
    } catch (error) {
        return res.status(400).json({ error: error.message });
    }
};
